WITH filtered AS (SELECT *, TO_DATE(started_at) AS started_at_date, INITCAP(TRIM(browser)) AS browser_title, COALESCE(browser, 'OTHER') AS browser_clean FROM sessions WHERE country IN ('UK', 'DE', 'SG')), with_prev AS (SELECT *, LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC) AS prev_started_at FROM filtered), with_gaps AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL '30' DAY THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), sessions_sessions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT CASE WHEN burst_id >= 9 THEN 'HIGH' ELSE 'LOW' END AS burst_id_tier, DATE_TRUNC('YEAR', prev_started_at) AS year_start, COUNT(*) AS cnt, PERCENTILE_APPROX(burst_id, ARRAY(0.25, 0.5, 0.75)) AS burst_id_quartiles, (UNIX_TIMESTAMP(MAX(prev_started_at)) - UNIX_TIMESTAMP(MIN(prev_started_at))) / 60 AS duration_min, APPROX_PERCENTILE(burst_id, ARRAY(0.25, 0.5, 0.75)) AS burst_id_quartiles_2, ROUND(AVG(burst_id), 2) AS avg_burst_id, COUNT(*) AS row_count, PERCENT_RANK() OVER (PARTITION BY CASE WHEN burst_id >= 9 THEN 'HIGH' ELSE 'LOW' END ORDER BY COUNT(*) DESC) AS row_count_percent_rank FROM sessions_sessions GROUP BY CASE WHEN burst_id >= 9 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('YEAR', prev_started_at) HAVING (UNIX_TIMESTAMP(MAX(prev_started_at)) - UNIX_TIMESTAMP(MIN(prev_started_at))) / 60 < 1000000 ORDER BY cnt DESC NULLS FIRST
